"""Isolated SILK worker. Paths are generated by audio_model, never by a message."""
from __future__ import annotations

import io
from pathlib import Path
import sys
import wave

_INPUT_LIMIT = 8 * 1024 * 1024
_PCM_LIMIT = 60 * 24000 * 2


class _ExcerptComplete(Exception):
    pass


class _BoundedPCM(io.BytesIO):
    def write(self, data):
        available = _PCM_LIMIT - self.tell()
        written = super().write(data[:available])
        if written < len(data) or self.tell() == _PCM_LIMIT:
            raise _ExcerptComplete
        return written


def _validated_stream(data):
    """Reject malformed packet lengths before native code, including terminal -1 markers."""
    if not isinstance(data, bytes) or not 12 <= len(data) <= _INPUT_LIMIT:
        raise ValueError("invalid_silk")
    header = 10 if data.startswith(b"\x02#!SILK_V3") else 9 if data.startswith(b"#!SILK_V3") else 0
    if not header:
        raise ValueError("invalid_silk")
    cursor = header
    packets = 0
    while cursor < len(data):
        if cursor + 2 > len(data):
            raise ValueError("invalid_silk")
        size = int.from_bytes(data[cursor:cursor+2], "little", signed=True)
        if size == -1 and cursor + 2 == len(data):
            data = data[:cursor]
            break
        if not 0 < size <= 960 or cursor + size + 2 > len(data):
            raise ValueError("invalid_silk")
        cursor += size + 2
        packets += 1
        # A packet has at least one 20 ms frame. Only the first minute is decoded.
        if packets == 3000:
            data = data[:cursor]
            break
    if not packets:
        raise ValueError("invalid_silk")
    return io.BytesIO(data)


def decode_file(source, destination):
    import pysilk

    source = Path(source)
    if not 12 <= source.stat().st_size <= _INPUT_LIMIT:
        raise ValueError("invalid_silk")
    stream = _validated_stream(source.read_bytes())
    with stream, _BoundedPCM() as pcm:
        try:
            pysilk.decode(stream, pcm, 24000)
        except _ExcerptComplete:
            pass
        if not 0 < pcm.tell() <= _PCM_LIMIT or pcm.tell() % 2:
            raise ValueError("invalid_pcm")
        with wave.open(str(destination), "wb") as output:
            output.setnchannels(1)
            output.setsampwidth(2)
            output.setframerate(24000)
            output.writeframes(pcm.getvalue())


def _main():
    # The parent also has a wall-clock deadline and always kills/reaps this process.
    if sys.platform == "linux":
        import resource
        resource.setrlimit(resource.RLIMIT_AS, (256 * 1024 * 1024, 256 * 1024 * 1024))
        resource.setrlimit(resource.RLIMIT_FSIZE, (4 * 1024 * 1024, 4 * 1024 * 1024))
        resource.setrlimit(resource.RLIMIT_CPU, (8, 8))
    if len(sys.argv) != 3:
        return 1
    try:
        decode_file(sys.argv[1], sys.argv[2])
    except Exception:
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(_main())
